def photo(n,alt,cls='',eager=False):
 return f'<img class="{cls}" src="assets/100088{n}.webp" alt="{alt}" loading="{"eager" if eager else "lazy"}" decoding="async">'
def button(text,href,cls='primary'):return f'<a class="button {cls}" href="{href}">{text} <span aria-hidden="true">↗</span></a>'
def header(active):return '''<a class="skip" href="#main">Skip to content</a><div class="topbar"><span>From Tangalle, with a love for the island.</span><a href="tel:+94769789949">Let’s talk: +94 76 978 9949</a></div><header class="header"><a class="brand" href="index.html" aria-label="Ceylon Safari Tours home"><img src="assets/1000881305.webp" alt="Ceylon Safari Tours logo" width="76" height="76"><span>CEYLON<span class="brand-sub">SAFARI TOURS</span></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">'''+''.join(f'<a href="{url}" {"aria-current=page" if active==url else ""}>{name}</a>' for url,name in nav)+f'</nav><a class="header-cta" href="contact.html">Plan your trip <span aria-hidden="true">↗</span></a></header>'
def footer():return f'''<footer><div class="footer-main wrap"><div><a class="footer-brand" href="index.html">Ceylon Safari Tours<span>THE ISLAND, AT YOUR PACE.</span></a><p>Safaris, travels & bike rentals.<br>Rooted in Tangalle, Sri Lanka.</p></div><div><h2>Explore</h2><a href="travels.html">Travels & safaris</a><a href="bike-rentals.html">Bike rentals</a><a href="about.html">Our story</a></div><div><h2>Say ayubowan</h2><a href="tel:+94769789949">+94 76 978 9949</a><a href="{WA}" target="_blank" rel="noopener">Chat on WhatsApp ↗</a><a href="{FB}" target="_blank" rel="noopener">Find us on Facebook ↗</a></div><div><h2>Find your starting point</h2><p>Tangalle, Southern Province<br>Sri Lanka</p><a href="https://www.google.com/maps/search/?api=1&query=Tangalle%2C%20Sri%20Lanka" target="_blank" rel="noopener">Explore Tangalle on the map ↗</a></div></div><div class="footer-bottom wrap"><span>© <span data-year>2026</span> Ceylon Safari Tours.</span><span>A warm welcome. A memorable journey.</span></div></footer><a class="floating-wa" href="{WA}" aria-label="Chat with Ceylon Safari Tours on WhatsApp" target="_blank" rel="noopener"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M21 11.5a9 9 0 0 1-13.4 7.9L3 21l1.5-4.5A9 9 0 1 1 21 11.5Z"/><path d="M8 7c-2 4 3 9 7 8l1-2-3-1-1 1-2-2 1-1-1-3Z"/></svg><span>Let’s chat</span></a>'''
def banner(title='Your next story starts in Tangalle.',text='A safari, an island journey, or a bike and an open road. Tell us what you have in mind.'):
 return f'<section class="cta-band"><div class="wrap"><span class="eyebrow">COME FOR THE ISLAND. STAY FOR THE MEMORIES.</span><h2>{title}</h2><p>{text}</p>{button("Let’s plan it together","contact.html","gold")}</div><span class="sun-mark" aria-hidden="true">☀</span></section>'
def intro(k,t,p):return f'<section class="page-intro wrap"><p class="eyebrow">{k}</p><h1>{t}</h1><p class="lead">{p}</p></section>'
form='''<form id="enquiry-form"><div class="form-grid"><label>Your name<input name="name" autocomplete="name" required maxlength="100" placeholder="How should we call you?"></label><label>I’m interested in<select name="service" required><option value="">Choose your adventure</option><option>Safari</option><option>Private travels / day trip</option><option>Bike rental</option><option>Something else</option></select></label><label>Preferred date<input type="date" name="date" required></label><label>Guests / riders<input type="number" name="guests" min="1" max="99" step="1" value="2" required></label><label class="full">Tell us a little more<textarea name="message" rows="4" maxlength="2000" placeholder="Pickup location, rental duration, places you would love to see…"></textarea></label></div><button class="button primary" type="submit">Continue to WhatsApp <span aria-hidden="true">↗</span></button><p class="form-note">This opens WhatsApp with your enquiry ready to send. Availability and prices are confirmed by our team. Your enquiry is not a confirmed booking.</p></form>'''
home=f'''<section class="home-hero"><div class="hero-copy"><p class="eyebrow"><span class="small-sun" aria-hidden="true">✳</span> TANGALLE · SRI LANKA</p><h1>A little wild.<br>A lot of <em>Ceylon.</em></h1><p>Open roads. Wild encounters. A warm island welcome. Discover Sri Lanka with Ceylon Safari Tours.</p><div class="hero-actions">{button('Find your adventure','travels.html') }<a class="text-link" href="bike-rentals.html">Or, rent a bike <span aria-hidden="true">→</span></a></div><div class="hero-bottom"><span class="tiny-line"></span><span>YOUR ISLAND ADVENTURE<br>BEGINS RIGHT HERE.</span></div></div><div class="hero-photo">{photo('1321','Travellers beside safari jeeps with Ceylon Safari Tours','',True)}<span class="image-corner">GOOD COMPANY.<br>GREAT ADVENTURES.</span><div class="photo-caption"><span>01 / THE SAFARI LIFE</span><span>Made for the memories ↗</span></div></div><a class="hero-scroll" href="#explore">SCROLL TO EXPLORE <span aria-hidden="true">↓</span></a></section><div class="ticker" aria-label="Our services"><span>SAFARI DAYS</span><b aria-hidden="true">✳</b><span>ISLAND TRAVELS</span><b aria-hidden="true">✳</b><span>BIKE RENTALS</span><b aria-hidden="true">✳</b><span>LOCAL CONNECTIONS</span></div>
<section id="explore" class="wrap section"><div class="section-head"><div><p class="eyebrow">ONE ISLAND. YOUR WAY.</p><h2>Take the scenic route.</h2></div><p>For the wildlife lovers, the curious wanderers,<br>and everyone who likes a little freedom.</p></div><div class="experience-grid"><a class="experience" href="travels.html#safari"><div class="experience-image">{photo('1313','Guests ready for an open-air safari jeep adventure')}<span class="round-arrow" aria-hidden="true">↗</span><span class="photo-label">01 / INTO THE WILD</span></div><h3>Safari adventures</h3><p>A jeep, a sense of wonder, and the wild side of Sri Lanka.</p></a><a class="experience" href="travels.html"><div class="experience-image">{photo('1309','A traveller and local host exploring a Sri Lankan temple')}<span class="round-arrow" aria-hidden="true">↗</span><span class="photo-label">02 / BEYOND THE GUIDEBOOK</span></div><h3>Travels & day trips</h3><p>Make room for beautiful places and unplanned discoveries.</p></a><a class="experience bike-card" href="bike-rentals.html"><div class="experience-image bike-art"><span class="art-sun" aria-hidden="true"></span><img src="assets/bike.svg" alt="Illustration of a motorcycle on a coastal road"><span class="round-arrow" aria-hidden="true">↗</span><span class="photo-label">03 / YOUR OWN RHYTHM</span></div><h3>Bike rentals</h3><p>Slow mornings. Coastal roads. The freedom to go your way.</p></a></div></section>
<section class="story-section"><div class="wrap story-grid"><div class="story-photos">{photo('1306','Travellers sharing fresh coconuts beside a lake','story-main')}<span class="story-stamp">AYUBOWAN!<br><small>WELCOME TO OUR ISLAND</small></span></div><div class="story-copy"><p class="eyebrow">A LOCAL HELLO GOES A LONG WAY</p><h2>Not just places.<br><em>People, too.</em></h2><p>We’re Ceylon Safari Tours, a travel and bike rental business based in Tangalle. We bring together the journeys, the rides, and the friendly island welcome.</p><p>Tell us what a great day looks like to you. We’ll help arrange a way to experience it.</p>{button('Get to know us','about.html','outline')}</div></div></section>
<section class="wrap section"><div class="section-head"><div><p class="eyebrow">A GLIMPSE OF THE GOOD TIMES</p><h2>Real days. Real memories.</h2></div><a class="text-link" href="{FB}" target="_blank" rel="noopener">More from our Facebook ↗</a></div><div class="memory-grid">{photo('1312','Guests enjoying their safari jeep outing')}{photo('1315','Elephants seen through the trees on safari')}{photo('1311','Travellers sharing a meal beside a safari jeep')}{photo('1307','Guests with luggage beside their transport')}</div><p class="gallery-note">Moments from our journeys, shared through our own photos.</p></section>{banner()}'''
travels=intro('THE JOURNEY IS PART OF THE STORY','More island.<br><em>More to remember.</em>','From safari days to journeys beyond Tangalle, let’s arrange a trip around what you want to experience.')+f'''<section id="safari" class="wrap travel-feature"><div class="feature-photo">{photo('1313','Open safari jeep with travellers ready for their journey','',True)}</div><div class="feature-copy"><p class="eyebrow">01 / THE WILD SIDE</p><h2>Out of the ordinary.<br>Into the wild.</h2><p>Experience the excitement of an open-air jeep adventure. Tell us your dates, group size, and the safari you have in mind, and we’ll discuss the arrangements with you.</p><ul class="simple-list"><li>Safari trip enquiries</li><li>Pickup arrangements discussed with you</li><li>A plan suited to your group</li></ul>{button('Ask about a safari','contact.html?service=Safari')}<p class="fine">Routes, entry tickets, inclusions, and prices are agreed before booking. Wildlife sightings depend on nature.</p></div></section><section class="wrap section"><div class="section-head"><div><p class="eyebrow">02 / YOUR ISLAND ITINERARY</p><h2>Where shall we go?</h2></div><p>Share your wish list.<br>We’ll help you work out the journey.</p></div><div class="two-grid"><article class="travel-card">{photo('1309','Travellers at a Sri Lankan cultural site')}<div><span class="eyebrow">CULTURE & EXPLORING</span><h3>Make a day of it.</h3><p>Ask us about arranging a day trip from Tangalle. Combine the places that interest you into a journey that feels like yours.</p><a class="text-link" href="contact.html?service=Private%20travels%20%2F%20day%20trip">Plan a day trip ↗</a></div></article><article class="travel-card">{photo('1308','Transport vehicle used for island travels')}<div><span class="eyebrow">PRIVATE TRAVELS</span><h3>A journey that fits.</h3><p>Have a pickup, onward journey, or a longer route in mind? Share your locations, luggage needs, and travel dates for a quote.</p><a class="text-link" href="contact.html?service=Private%20travels%20%2F%20day%20trip">Discuss your route ↗</a></div></article></div></section><section class="how-section"><div class="wrap"><p class="eyebrow">LESS PLANNING. MORE LOOKING FORWARD.</p><h2>From hello to let’s go.</h2><div class="steps"><div><span>01</span><h3>Tell us your idea</h3><p>Your dates, your group, and what you would love to do.</p></div><div><span>02</span><h3>Make a plan together</h3><p>We discuss the route, availability, inclusions, and quote.</p></div><div><span>03</span><h3>Confirm & explore</h3><p>Agree the details with our team, then look forward to the journey.</p></div></div></div></section>{banner('Let’s put your trip on the map.')}'''
bikes=intro('TWO WHEELS. ENDLESS LITTLE DISCOVERIES.','The coast is calling.<br><em>Go your own way.</em>','Ask about bike rentals in Tangalle and enjoy the freedom to explore Sri Lanka at your own pace.')+f'''<section class="wrap rental-feature"><div class="rental-art"><span class="eyebrow">TANGALLE · SRI LANKA</span><span class="big-sun" aria-hidden="true"></span><img src="assets/bike.svg" alt="Illustration of a motorcycle with a coastal road and palms"><span class="rental-art-caption">LESS RUSH. MORE ISLAND.</span><span class="illustration-note">Illustration — ask us for current bike photos.</span></div><div class="feature-copy"><p class="eyebrow">FIND YOUR FREEDOM</p><h2>Your ride.<br>Your kind of day.</h2><p>Whether you’re planning short local rides or a little longer on the road, tell us the kind of bike you’re looking for and your rental dates.</p><p>We’ll confirm available options, current photos, rates, and rental conditions with you before you decide.</p>{button('Check bike availability','contact.html?service=Bike%20rental')}<a class="rental-phone" href="tel:+94769789949">Or call +94 76 978 9949</a></div></section><section class="wrap section"><div class="section-head"><div><p class="eyebrow">A LITTLE PREPARATION GOES A LONG WAY</p><h2>Before you hit the road.</h2></div></div><div class="rental-details"><article><span>01 / CHOOSE YOUR DATES</span><h3>A day or a little longer?</h3><p>Send your preferred pickup date, return date, and rider count. Availability and rental duration will be confirmed directly.</p></article><article><span>02 / CONFIRM THE DETAILS</span><h3>Know your ride.</h3><p>Ask about the model, rate, deposit, helmet, fuel policy, mileage, insurance, and pickup or return arrangements.</p></article><article><span>03 / RIDE PREPARED</span><h3>Ready for the road.</h3><p>Bring the documents required to ride legally in Sri Lanka. Confirm licence and permit requirements before agreeing your rental.</p></article></div></section><section class="faq wrap"><p class="eyebrow">GOOD TO KNOW</p><h2>A few things you might ask.</h2><details><summary>Which bikes are available?</summary><p>Contact us with your dates and preferred type of bike. We’ll share the current options and photos. Models and availability can change.</p></details><details><summary>How much does a rental cost?</summary><p>Ask for a quote for your chosen bike and dates. Confirm the full rate, deposit, and any additional charges with our team before booking.</p></details><details><summary>Can I collect a bike in Tangalle?</summary><p>We are based in Tangalle. Contact us to agree the exact collection and return location before you travel.</p></details><details><summary>Is my enquiry a confirmed booking?</summary><p>No. Your bike rental is confirmed only after the availability, price, documents, and terms have been agreed directly with our team.</p></details></section>{banner('Find your own favourite road.','Tell us your dates. We’ll help you find the right ride.')}'''
about=intro('AYUBOWAN. WE’RE GLAD YOU’RE HERE.','A local start.<br><em>A world of memories.</em>','Meet Ceylon Safari Tours — travels, safari adventures, and bike rentals from Tangalle, Sri Lanka.')+f'''<section class="wrap about-layout"><div class="about-photo">{photo('1306','Friendly moments with travellers and fresh coconuts in Sri Lanka','',True)}</div><div class="about-copy"><p class="eyebrow">OUR CORNER OF CEYLON</p><h2>From Tangalle,<br>with a warm welcome.</h2><p>Our business brings together a simple idea: help people enjoy the island in a way that suits them.</p><p>For some, that means a day in a safari jeep. For others, it’s a private journey, a cultural stop, or the freedom of a rented bike. We arrange travels and bike rentals, with Tangalle as our home base.</p><p>We believe a good trip starts with a conversation. You share the idea; we talk through the details together.</p><a class="text-link" href="contact.html">Come say hello ↗</a></div></section><section class="values-section"><div class="wrap"><p class="eyebrow">THE WAY WE TRAVEL</p><h2>A little closer to the island.</h2><div class="steps"><div><span>✳</span><h3>Start with you</h3><p>Your interests, your dates, your pace. Every enquiry begins with what you have in mind.</p></div><div><span>↗</span><h3>Keep it personal</h3><p>Speak directly with our team to work through your travel or rental arrangements.</p></div><div><span>☀</span><h3>Make room for moments</h3><p>The conversations, the coconut stops, and the shared smiles are part of the journey.</p></div></div></div></section><section class="wrap section"><div class="section-head"><div><p class="eyebrow">FACES, PLACES & OPEN ROADS</p><h2>The people make it special.</h2></div></div><div class="about-gallery">{photo('1310','Travellers sharing a ride with Ceylon Safari Tours')}{photo('1307','Travellers with their luggage beside a vehicle')}{photo('1319','Guests seated in a safari jeep')}</div></section>{banner()}'''
contact=intro('EVERY GOOD TRIP STARTS WITH A HELLO.','Let’s make<br><em>some plans.</em>','A safari, a trip, or a bike rental — tell us what you’re dreaming of.')+f'''<section class="wrap contact-layout"><aside><p class="eyebrow">CEYLON SAFARI TOURS</p><h2>Say ayubowan.</h2><p>Speak directly with us to discuss your dates, availability, and a personalised quote.</p><div class="contact-block"><span>CALL OR WHATSAPP</span><a class="big-phone" href="tel:+94769789949">076 978 9949</a><a href="{WA}" target="_blank" rel="noopener">International: +94 76 978 9949 ↗</a></div><div class="contact-block"><span>OUR HOME BASE</span><p>Tangalle<br>Southern Province, Sri Lanka</p><a class="text-link" href="https://www.google.com/maps/search/?api=1&query=Tangalle%2C%20Sri%20Lanka" target="_blank" rel="noopener">View Tangalle on the map ↗</a><p class="fine">Please contact us for the exact meeting or pickup point.</p></div><div class="contact-block"><span>FOLLOW THE JOURNEY</span><a href="{FB}" target="_blank" rel="noopener">Our Facebook ↗</a></div></aside><div class="enquiry-panel"><p class="eyebrow">YOUR NEXT ADVENTURE</p><h2>What have you got in mind?</h2>{form}</div></section><section class="contact-image wrap">{photo('1312','A group of travellers waving from an open-air safari jeep')}<span>SEE YOU ON THE ISLAND.</span></section>'''
pages=[('index.html','Ceylon Safari Tours | Travels & Bike Rentals in Tangalle','Discover Sri Lanka with Ceylon Safari Tours, Tangalle. Enquire about safari adventures, private travels, day trips and bike rentals. Call +94 76 978 9949.',home),('travels.html','Travels & Safari Adventures | Ceylon Safari Tours, Tangalle','Plan your next Sri Lankan safari or private journey with Ceylon Safari Tours in Tangalle. Discuss routes, availability and quotes directly on WhatsApp.',travels),('bike-rentals.html','Bike Rentals in Tangalle | Ceylon Safari Tours','Enquire about bike rentals in Tangalle, Sri Lanka. Contact Ceylon Safari Tours for available bikes, current rates and rental arrangements.',bikes),('about.html','About Us | Ceylon Safari Tours, Tangalle','Meet Ceylon Safari Tours, a travel and bike rental business based in Tangalle, Sri Lanka. A warm island welcome for your next journey.',about),('contact.html','Contact Ceylon Safari Tours | Tangalle, Sri Lanka','Contact Ceylon Safari Tours in Tangalle for safari, travels and bike rental enquiries. Call or WhatsApp +94 76 978 9949.',contact)]
for name,title,desc,body in pages:
 schema={'@context':'https://schema.org','@type':'TravelAgency','name':'Ceylon Safari Tours','telephone':'+94769789949','address':{'@type':'PostalAddress','addressLocality':'Tangalle','addressRegion':'Southern Province','addressCountry':'LK'},'areaServed':{'@type':'Country','name':'Sri Lanka'}}
